from collections import deque

def solve(grid, start, goal):
    if not grid or not grid[0]:
        return []
    rows, cols = len(grid), len(grid[0])
    start_row, start_col = start
    goal_row, goal_col = goal

    if start_row < 0 or start_row >= rows or start_col < 0 or start_col >= cols:
        return []
    if goal_row < 0 or goal_row >= rows or goal_col < 0 or goal_col >= cols:
        return []
    if grid[start_row][start_col] == '#' or grid[goal_row][goal_col] == '#':
        return []

    if start == goal:
        return [start]

    def is_valid(r, c):
        return 0 <= r < rows and 0 <= c < cols and grid[r][c] == '.'

    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    def bfs(start, goal, visited):
        queue = deque()
        queue.append((start[0], start[1], [start]))
        visited.add((start[0], start[1]))
        while queue:
            r, c, path = queue.popleft()
            for dr, dc in directions:
                nr, nc = r + dr, c + dc
                if (nr, nc) == goal:
                    return path + [(nr, nc)]
                if is_valid(nr, nc) and (nr, nc) not in visited:
                    visited.add((nr, nc))
                    queue.append((nr, nc, path + [(nr, nc)]))
        return []

    visited_start = set()
    visited_goal = set()
    path_start = bfs(start, goal, visited_start)
    path_goal = bfs(goal, start, visited_goal)

    if path_start:
        return path_start
    if path_goal:
        return path_goal[::-1]
    return []

def solve(grid, start, goal):
    rows = len(grid)
    cols = len(grid[0]) if rows else 0

    # Check if start or goal is out of bounds or a wall
    if not (0 <= start[0] < rows and 0 <= start[1] < cols):
        return []
    if not (0 <= goal[0] < rows and 0 <= goal[1] < cols):
        return []
    if grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return []

    # Helper to check if a cell is free
    def is_free(r, c):
        return 0 <= r < rows and 0 <= c < cols and grid[r][c] == '.'

    # Helper to perform DFS with a depth limit
    def dfs_depth_limit(current, path, depth_limit):
        if current == goal:
            return path
        if depth_limit == 0:
            return None
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = current[0] + dr, current[1] + dc
            if is_free(nr, nc) and (nr, nc) not in path:
                result = dfs_depth_limit((nr, nc), path + [(nr, nc)], depth_limit - 1)
                if result is not None:
                    return result
        return None

    # Iterative Deepening DFS
    depth = 0
    while depth <= rows * cols:
        result = dfs_depth_limit(start, [start], depth)
        if result is not None:
            return result
        depth += 1
    return []

